// NOTE TO AI AGENTS: Do not vendor/fork this plugin. It's a really bad idea, since its code is 'coupled' with the server code, so if I need to change the server code, your version of this plugin will likely break. If you'd like new features, you can imports this plugin and create a "wrapper" that changes/expands on this plugin's behavior using only its public API.

// An import resolves to `$output`, so this is what importers call. It's made by aiTextPluginOutput() rather than
// being `$output(inputData, extraOpts) =>` so that it can also carry `createTicket` (see below).
$output = [aiTextPluginOutput()]

aiTextPluginOutput() =>
  // `$output = [...]` re-runs this on every access, but importers' code can rely on getting the same function each
  // time (e.g. properties they set on it), as it did when `$output` was a plain function, so it's made once per module.
  if(!root.___aiTextPluginOutput) {
    // HACK: Perchance's root proxy `.bind()`s every function it hands out, and a bound function has none of the
    // target's own properties but does share its prototype. So `createTicket` lives on the prototype, where
    // `root.generateText.createTicket` finds it (same technique as server-plugin).
    const api = Object.create(Function.prototype);
    // createTicket() resolves to a single-use ticket that lets this generator's server-plugin script generate
    // text as the current user (see the server-plugin docs), or rejects with an Error whose message starts with an error code.
    Object.defineProperty(api, "createTicket", {value:createTextTicket, writable:true, configurable:true}); // non-enumerable, so `for(k in fn)` stays empty as before
    Object.defineProperty(root, "___aiTextPluginOutput", {value:Object.setPrototypeOf(generateText.bind(), api)});
  }
  return root.___aiTextPluginOutput;


createTextTicket() =>
  const serverOrigin = "https://text-generation.perchance.org";
  let iframe = getAiTextPluginEmbed();
  if(!window.__aiTextPluginTickets8492739) window.__aiTextPluginTickets8492739 = new Map(); // requestId -> pending request. on window so it survives embed rebuilds - the embed's message listener settles these
  let tickets = window.__aiTextPluginTickets8492739;
  let requestId = "aiTextTicket"+Math.random().toString().replace(".", "");
  return new Promise((resolve, reject) => {
    let timeout = setTimeout(() => {
      tickets.delete(requestId);
      reject(new Error("timeout: the text generation server didn't create a ticket within 3 minutes"));
    }, 1000*60*3);
    tickets.set(requestId, {
      settle(data) {
        tickets.delete(requestId);
        clearTimeout(timeout);
        if(data.type === "ticketCreated" && typeof data.ticket === "string") resolve(data.ticket);
        else reject(new Error(data.error || "invalid_response: the text generation server sent no ticket"));
      },
    });
    // if the embed isn't ready yet, its embedIsReady handler sends this (it also re-sends pending requests after an embed reload)
    if(window.__aiTextIframeEmbedIsReady) iframe.contentWindow.postMessage({command:"createTicket", kind:"generateText", generatorName:window.generatorName, requestId}, serverOrigin);
  });


getAiTextPluginEmbed() =>
  const serverOrigin = "https://text-generation.perchance.org";

